struct Structure : SectionFields {
    static constexpr std::string_view kind = "structure";
    Structure() { id = "structure"; }
    StructureFields fields;
    StructurePayload structure{};
    std::optional<BondsPayload> bonds{};
    std::string to_section(Writer& writer) const {
        Section s = descriptor(std::string(kind));
        const Json peer_fields = fields.to_json();
        for (const auto& kv : peer_fields.items()) s.extra.set(kv.first, kv.second);
        std::vector<JsonPayload> json; std::vector<BinaryPayload> binary; std::vector<OpaquePayload> opaque;
        json.push_back({"structure", codec::Value<StructurePayload>::encode(structure)});
        if (bonds) json.push_back({"bonds", codec::Value<BondsPayload>::encode((*bonds))});
        return writer.add_payload(std::move(s), json, binary, opaque);
    }
    static Structure from_section(const Reader& reader, const Section& section) {
        if (!section.kind || *section.kind != kind) throw std::invalid_argument("wrong section kind");
        Structure out; out.load(section);
        out.fields = StructureFields::from_json(section.extra);
        out.fields.extra.clear();
        out.extra = Json::object();
        for (const auto& kv : section.extra.items()) if (kv.first != "chains" && kv.first != "residues" && kv.first != "secondary_structure" && kv.first != "b_factors" && kv.first != "charge" && kv.first != "multiplicity" && kv.first != "name" && kv.first != "smiles" && kv.first != "inchi" && kv.first != "inchikey") out.extra.set(kv.first, kv.second);
        out.structure = codec::Value<StructurePayload>::decode(reader.json(section, "structure"));
        if (section.member("bonds")) out.bonds.emplace(codec::Value<BondsPayload>::decode(reader.json(section, "bonds")));
        return out;
    }
};

