struct RunRecord : SectionFields {
    static constexpr std::string_view kind = "run.record";
    RunRecord() { id = "run_record"; }
    RunRecordFields fields;
    std::optional<OpaqueData> input{};
    std::optional<OpaqueData> log{};
    std::optional<std::map<std::string, RunRecordFilesPayloadEntry0>> files{};
    std::map<std::string, OpaqueData> attachments{};
    std::string to_section(Writer& writer) const {
        Section s = descriptor(std::string(kind));
        const Json peer_fields = fields.to_json();
        for (const auto& kv : peer_fields.items()) s.extra.set(kv.first, kv.second);
        std::vector<JsonPayload> json; std::vector<BinaryPayload> binary; std::vector<OpaquePayload> opaque;
        if (input) opaque.push_back({"input", (*input).bytes, (*input).media_type});
        if (log) opaque.push_back({"log", (*log).bytes, (*log).media_type});
        if (files) json.push_back({"files", codec::Value<std::map<std::string, RunRecordFilesPayloadEntry0>>::encode((*files))});
        for (const auto& member : attachments) opaque.push_back({member.first, member.second.bytes, member.second.media_type});
        return writer.add_payload(std::move(s), json, binary, opaque);
    }
    static RunRecord from_section(const Reader& reader, const Section& section) {
        if (!section.kind || *section.kind != kind) throw std::invalid_argument("wrong section kind");
        RunRecord out; out.load(section);
        out.fields = RunRecordFields::from_json(section.extra);
        out.fields.extra.clear();
        out.extra = Json::object();
        for (const auto& kv : section.extra.items()) if (kv.first != "program" && kv.first != "program_version" && kv.first != "command" && kv.first != "exit_status" && kv.first != "started_utc" && kv.first != "finished_utc" && kv.first != "sequence" && kv.first != "job_ref" && kv.first != "run_status") out.extra.set(kv.first, kv.second);
        if (section.member("input")) out.input.emplace(OpaqueData{reader.bytes(section, "input"), section.member("input")->media_type});
        if (section.member("log")) out.log.emplace(OpaqueData{reader.bytes(section, "log"), section.member("log")->media_type});
        if (section.member("files")) out.files.emplace(codec::Value<std::map<std::string, RunRecordFilesPayloadEntry0>>::decode(reader.json(section, "files")));
        if (section.members) for (const auto& member : *section.members) if (member.first != "input" && member.first != "log" && member.first != "files") out.attachments.emplace(member.first, OpaqueData{reader.bytes(section, member.first), section.member(member.first)->media_type});
        return out;
    }
};

